import re
def parse(kind,occ=1):
    ms=list(re.finditer(kind+r' \((\d+)x(\d+)\):\n',t))
    m=ms[occ-1]
    h,w=int(m[1]),int(m[2])
    return [[int(x) for x in r.split()] for r in t[m.end():].split('\n')[:h]]
